import java.util.*;import java.util.jar.*;import org.objectweb.asm.*;import org.objectweb.asm.tree.*;import net.vulkanmod.gl.*;
/** Every original managed-state body reverses exactly, including constructors and restore control flow. */
public final class EssentialManagedStateCallerRegression {
    static ClassNode read(byte[] raw){var node=new ClassNode();new ClassReader(raw).accept(node,0);return node;}
    static void require(boolean ok,String why){if(!ok)throw new AssertionError(why);}
    static void reject(ClassNode node){try{EssentialManagedStateCallers.apply(node);throw new AssertionError("Unreviewed state accepted");}catch(IllegalStateException expected){}}
    public static void main(String[]args)throws Exception{int controls=0,total=0;String[] names={"gg/essential/universal/render/ManagedGlState","gg/essential/universal/render/ManagedGlState$Companion","gg/essential/universal/shader/BlendState","gg/essential/universal/shader/BlendState$Companion"};int[] counts={1,10,4,6};try(var jar=new JarFile(args[0])){for(int i=0;i<names.length;i++){byte[] raw=jar.getInputStream(jar.getJarEntry(names[i]+".class")).readAllBytes();ClassNode original=read(raw),node=read(raw);String before=ShaderCallerRemapper.canonicalDigest(original);var result=EssentialManagedStateCallers.apply(node);require(result.calls()==counts[i],"exact state call scope");total+=result.calls();controls++;reject(node);controls++;var unknown=read(raw);unknown.name="unknown/State";reject(unknown);controls++;var changed=read(raw);changed.methods.get(0).instructions.insert(new InsnNode(Opcodes.NOP));reject(changed);controls++;
        for(int m=0;m<node.methods.size();m++){var old=original.methods.get(m);var now=node.methods.get(m);List<MethodInsnNode>a=new ArrayList<>(),b=new ArrayList<>();for(var in:old.instructions)if(in instanceof MethodInsnNode c)a.add(c);for(var in:now.instructions)if(in instanceof MethodInsnNode c)b.add(c);require(a.size()==b.size(),"original state topology");for(int c=0;c<a.size();c++){var x=a.get(c);var y=b.get(c);if(y.owner.equals(EssentialManagedStateCallers.FACADE)){require(x.getOpcode()==Opcodes.INVOKESTATIC&&y.name.equals(x.name)&&y.desc.equals(x.desc)&&!y.itf,"only original same-signature static call owners");y.owner=x.owner;}else require(y.owner.equals(x.owner)&&y.name.equals(x.name)&&y.desc.equals(x.desc),"unrelated state calls unchanged");}}
        require(before.equals(ShaderCallerRemapper.canonicalDigest(node)),"all original state bodies inverse identical");controls++;
    }}require(total==21,"total state calls");System.out.println("ESSENTIAL_MANAGED_CALLER_PASS controls="+controls+" stateCalls="+total+" allOriginalBodiesInverseIdentical=true");}
}
